arguments.command:
python3 -c "
from pptx import Presentation
prs = Presentation('/app/output/final_deck.pptx')
for i, slide in enumerate(prs.slides, 1):
    all_text = ' | '.join(
        s.text_frame.text[:50].replace(chr(10),' ')
        for s in slide.shapes if s.has_text_frame and s.text_frame.text.strip()
    )
    print(f'S{i}: {all_text[:120]}')
"

